'{
  "data": {"name": "dataset"},

  "params": [
    { "name": "linha_cor", "value": "#E0AE55" },
    { "name": "linha_espessura", "value": 3 },

    { "name": "marcador_cor", "value": "#E0AE55" },
    { "name": "marcador_tam", "value": 0 },
    { "name": "marcador_espessura", "value": 2 },

    { "name": "valor_cor", "value": "#ECE9E2" },
    { "name": "valor_tam", "value": 10 },
    { "name": "valor_peso", "value": 500 },
    { "name": "valor_posicao", "value": -14 },

    { "name": "perc_tam", "value": 9 },
    { "name": "perc_peso", "value": 600 },
    { "name": "perc_posicao", "value": -28 }
  ],

  "transform": [
    {
      "calculate": "datum[''Month-over-month growth (%)''] > 0",
      "as": "perc_positivo"
    },
    {
      "calculate": "datum[''perc_positivo''] ? ''#5FBE86'' : ''#E2685A''",
      "as": "perc_cor"
    }
  ],

  "encoding": {
    "x": {
      "type": "nominal",
      "field": "Month Name",
      "sort": {"field": "Year Month Number"},
      "axis": {
        "labelAngle": 0,
        "labelPadding": 10
      }
    },
    "y": {
      "type": "quantitative",
      "field": "Total Revenue",
      "axis": null
    },

    "opacity": {
      "condition": {
        "test": "datum[''__selected__''] == ''off''",
        "value": 0.3
      },
      "value": 1
    },

    "tooltip": [
      {"field": "Month Year"},
      {"field": "Total Revenue", "formatType": "pbiFormat", "format": "R$ #,##0.00"},
      {"field": "Month-over-month growth (%)", "formatType": "pbiFormat", "format": "+0.0%;-0.0%"}
    ]
  },
  "layer": [
    {
      "mark": {
        "type": "area",
        "interpolate": "natural",

        "line": {
          "stroke": { "expr": "linha_cor" },
          "strokeWidth": { "expr": "linha_espessura" },
          "strokeCap": "round",
          "strokeDash": [0, 0]
        },

        "point": {
          "shape": "circle",
          "size": { "expr": "marcador_tam" },
          "filled": false,
          "fill": { "expr": "marcador_cor" },
          "stroke": { "expr": "linha_cor" },
          "strokeWidth": { "expr": "marcador_espessura" },
          "tooltip": true
        }
      }
    },

    {
      "description": " ---------------- Valor -------------------------- ",
      "mark": {
        "type": "text",
        "baseline": "bottom",
        "dy": { "expr": "valor_posicao" },
        "color": { "expr": "valor_cor" },
        "fontSize": { "expr": "valor_tam" },
        "fontWeight": { "expr": "valor_peso" }
      },
      "encoding": {
        "text": {
          "field": "Total Revenue",
          "format": ".3~s"
        }
      }
    },

    {
      "description": " ---------------- Porcentagem -------------------------- ",
      "mark": {
        "type": "text",
        "color": { "expr": "datum[''Month-over-month growth (%)''] == null ? ''transparent'' : datum[''perc_cor'']" },
        "baseline": "bottom",
        "dy": { "expr": "perc_posicao" },
        "fontSize": { "expr": "perc_tam" },
        "fontWeight": { "expr": "perc_peso" },
        "font": "Segoe UI"
      },
      "encoding": {
        "text": {
          "field": "Month-over-month growth (%)",
          "formatType": "pbiFormat",
          "format": "+0% ⮝;-0% ⮟; 0%"
        }
      }
    }
  ]
}'

'{
  "view": {"stroke": "transparent"},

  "font": "Segoe UI",

  "area": {
    "color": {
      "x1": 1,
      "x2": 1,
      "y1": 1,
      "y2": 0,
      "gradient": "linear",
      "stops": [
        { "offset": 0, "color": "rgba(224,174,85, 0)" },
        { "offset": 0.15, "color": "rgba(224,174,85, 0.03)" },
        { "offset": 0.3, "color": "rgba(224,174,85, 0.1)" },
        { "offset": 1, "color": "rgba(224,174,85, 0.5)" }
      ]
    }
  },

  "axis": {
    "ticks": false,
    "grid": false,
    "domain": false,
    "labelFontSize": 10,
    "labelFontWeight": 400,
    "labelColor": "#9CA3AF",
    "title": null
  },
  "axisQuantitative": {
    "tickCount": 3,
    "grid": true,
    "gridColor": "#3A4250",
    "gridOpacity": 0.5,
    "gridDash": [1, 5],
    "labelFlush": false
  },
  "line": {
    "strokeCap": "round",
    "strokeJoin": "round"
  },
  "axisX": {"labelPadding": 5},
  "axisY": {"labelPadding": 10},
  "header": {
    "titleColor": "#FFFFFF",
    "labelFont": "Segoe UI",
    "labelFontSize": 13.333333333333332,
    "labelColor": "#D2D0CE"
  }
}'
